import{START,END,minute,time,istNow,dayOf,evaluate,parseSearch}from './engine.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,live=true,currentResults=[],mapTimer=null,selectedMapRoom=null;const fields=['date','time','duration','floor','ac','people'];
const read=()=>Object.fromEntries(fields.map(k=>[k,$(k).value]));
function apply(q){for(const k of fields){if(k==='duration'&&![...$('duration').options].some(o=>o.value===String(q[k])))$('duration').add(new Option(`${q[k]} minutes`,q[k]));$(k).value=q[k]} }
function metadata(room){return room}
const floorName=f=>f===null?'Floor not mapped':['Ground floor','First floor','Second floor'][f];
function render(){if(!data)return;const q=read();const start=minute(q.time),end=start+Number(q.duration);if(dayOf(q.date)<0||!Number.isFinite(start)||!Number.isFinite(end)||Number(q.duration)<=0||(q.people&&(!Number.isInteger(Number(q.people))||Number(q.people)<1||Number(q.people)>1000))){$('results').innerHTML='<div class="empty"><h3>Check your filters</h3><p>Enter a valid date, time, duration, and group size.</p></div>';$('stats').innerHTML='';$('windowLabel').textContent='';currentResults=[];return}currentResults=data.rooms.map(r=>evaluate(metadata(r),data.events,q));const matching=currentResults.filter(r=>r.match).length,occupied=currentResults.filter(r=>r.current.length).length,unknown=currentResults.filter(r=>r.missing.length).length;const weekday=new Intl.DateTimeFormat('en-IN',{weekday:'long',day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(q.date+'T12:00:00Z'));$('windowLabel').textContent=`${weekday} · ${q.time}–${time(end)} IST · ${q.duration} minutes${live?' · Updates every minute':''}`;$('stats').innerHTML=`<div class="stat"><b>${matching}</b>matching classrooms</div><div class="stat"><b>${occupied}</b>with a class at start</div><div class="stat"><b>${data.rooms.length}</b>tracked venues</div>${unknown?`<div class="stat"><b>${unknown}</b>missing requested details</div>`:''}`;
if(!currentResults[0].known){$('results').innerHTML=`<div class="empty"><h3>${dayOf(q.date)===0||dayOf(q.date)===6?'No weekend timetable supplied':'Outside the timetable window'}</h3><p>Choose a weekday and a stay entirely between 09:00 and 16:50 IST.<br>Room availability outside this window is unknown.</p><button class="textbutton" id="sampleTime">View Monday, 13:20–14:20</button></div>`;$('sampleTime').onclick=()=>{let d=istNow().date;let delta=(1-dayOf(d)+7)%7;let dt=new Date(d+'T12:00:00Z');dt.setUTCDate(dt.getUTCDate()+delta);apply({...read(),date:dt.toISOString().slice(0,10),time:'13:20',duration:60});live=false;render()};return}
let visible=currentResults.filter(r=>!$('onlyFree').checked||r.match);if(q.floor!=='all')visible=visible.filter(r=>q.floor==='unknown'?r.room.floor===null:String(r.room.floor)===q.floor);visible.sort((a,b)=>Number(b.match)-Number(a.match)||a.room.name.localeCompare(b.room.name));let html='';if(!matching){html+=`<div class="empty"><h3>No exact matches for this stay</h3><p>${unknown?'Some rooms are missing the floor, AC, or capacity details you requested. Add confirmed details or relax those filters.':'Try a shorter stay or another time. Labs are not offered as study rooms.'}</p><button class="textbutton" id="emptyDetails">Add confirmed room details ↗</button></div>`}
const groups=q.floor==='all'?(currentResults.some(r=>r.room.floor!==null)?[0,1,2,null]:[null,0,1,2]):q.floor==='unknown'?[null]:[Number(q.floor)];for(const f of groups){const rooms=visible.filter(r=>r.room.floor===f);if(!rooms.length&&f===null)continue;html+=`<div class="floor-section"><div class="floor-title"><span class="floor-number">${f===null?'?':String(f).padStart(2,'0')}</span><h3>${floorName(f)}</h3><p>${rooms.length?`${rooms.filter(r=>r.match).length} match${rooms.filter(r=>r.match).length===1?'':'es'} · ${rooms.length} venues`:'No rooms mapped yet'}</p></div>${rooms.length?`<div class="room-grid">${rooms.map(card).join('')}</div>`:`<div class="floor-empty">${$('onlyFree').checked?'No matching rooms on this floor.':'Add confirmed floor details to place rooms here.'}</div>`}</div>`}$('results').innerHTML=html;renderMap();document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>roomDetails(b.dataset.room));if($('emptyDetails'))$('emptyDetails').onclick=openMetadata}
function card(r){const room=r.room;let badge=r.match?'Matches stay':({busy:'Class in progress',short:'Too short',lab:'Lab · restricted',filtered:'No exact match',unknown:'Unknown'})[r.status]||'No listed class';let label=r.current.length?`Class ends ${time(Math.max(...r.current.map(e=>e.end)))}`:`No listed class until ${time(r.freeUntil)}`;if(r.status==='short')label=`Only ${r.freeUntil-r.start} minutes free`;if(r.status==='filtered'&&r.missing.length)label=`${r.missing.join(', ')} not provided`;const ac=room.ac===null?'AC unknown':room.ac?'AC':'Non-AC';const cap=room.capacity!==null?`${room.capacity} seats`:(room.capacityRange||'Seats unknown');const coverage=room.coverage==='full'?'Combined schedule':room.coverage==='FN'?'Morning section only':room.coverage==='AN'?'Afternoon section only':'Partial room schedule';return `<button class="room-card" data-room="${room.id}" aria-label="${esc(room.name)}, ${esc(badge)}, view schedule"><div class="card-top"><span class="room-name">${esc(room.name)}</span><span class="badge ${r.match?'free':r.status==='busy'?'busy':r.status==='short'?'short':''}">${badge}</span></div><div class="card-info"><p class="until">${label}</p><p class="room-meta">${ac} · ${cap}<br>${room.type==='lab'?'Teaching laboratory':coverage}</p><div class="timeline" aria-hidden="true">${r.list.map(e=>`<i style="left:${100*(e.start-START)/(END-START)}%;width:${100*(e.end-e.start)/(END-START)}%"></i>`).join('')}<i class="window" style="left:${100*(r.start-START)/(END-START)}%;width:${100*(r.end-r.start)/(END-START)}%"></i></div><div class="timeline-label"><span>09:00</span><span>16:50</span></div></div><div class="card-bottom"><span>${r.match?'Timetable gap · confirm access':'View day schedule'}</span><span aria-hidden="true">↗</span></div></button>`}
function countdownLabel(r){
  const now=new Date();
  const q=read();
  const today=istNow().date;
  const isToday=q.date===today;
  const n=r.next;
  if(!isToday||!n)return {text:'Next class time unavailable',seconds:null};
  const target=new Date();
  target.setHours(Math.floor(n.start/60),n.start%60,0,0);
  let seconds=Math.max(0,Math.floor((target-now)/1000));
  if(seconds===0)return {text:'Starting now',seconds:0};
  const h=Math.floor(seconds/3600),m=Math.floor((seconds%3600)/60),sec=seconds%60;
  return {text:`Next class in ${h?`${h}h `:''}${m?`${m}m `:''}${String(sec).padStart(2,'0')}s`,seconds};
}
function mapStatus(r){
  if(!r.known)return 'unknown';
  if(r.current.length)return 'busy';
  if(r.room.type==='lab')return 'unknown';
  const cd=countdownLabel(r);
  if(cd.seconds!==null&&cd.seconds<=30*60)return 'soon';
  if(r.free)return 'free';
  return 'soon';
}
function mapRoomsByLevel(){
  const groups=new Map([['Ground floor',[]],['First floor',[]],['Second floor',[]],['Unmapped',[]]]);
  currentResults.forEach(r=>{
    const key=r.room.floor===0?'Ground floor':r.room.floor===1?'First floor':r.room.floor===2?'Second floor':'Unmapped';
    groups.get(key).push(r);
  });
  return [...groups.entries()].filter(([,rooms])=>rooms.length);
}
function renderMap(){
  const host=$('buildingMap'); if(!host||!currentResults.length)return;
  const levels=mapRoomsByLevel();
  host.innerHTML=`<div class="map-building">${levels.map(([label,rooms],li)=>{
    const shown=rooms.slice(0,18);
    return `<section class="map-floor" aria-label="${esc(label)}"><div class="map-floor-label"><span>${esc(label)}</span><small>${rooms.length} rooms</small></div><div class="map-room-grid">${shown.map((r,i)=>{
      const st=mapStatus(r),cd=countdownLabel(r),label=st==='free'?'FREE':st==='busy'?'BUSY':st==='soon'?'SOON':'UNKNOWN';
      const sub=st==='busy'?(r.current[0]?`Until ${time(r.current[0].end)}`:'Occupied'):cd.text;
      return `<button type="button" class="map-room map-${st}" data-map-room="${esc(r.room.id)}" aria-label="${esc(r.room.name)}, ${label}. ${esc(sub)}"><span class="map-room-name">${esc(r.room.name)}</span><strong>${label}</strong><small>${esc(sub)}</small></button>`;
    }).join('')}</div></section>`;
  }).join('')}</div><p class="map-note">Schematic / not to scale · colors are calculated from the supplied timetable and current selected date/time.</p>`;
  host.querySelectorAll('[data-map-room]').forEach(b=>b.addEventListener('click',()=>roomDetails(b.dataset.mapRoom)));
}
function inviteWhatsApp(r){
  const q=read(), until=r.freeUntil===END?'end of timetable':time(r.freeUntil);
  const msg=`📍 Heading to ${r.room.name}. It's free until ${until}. Come fast!`;
  const url=`https://wa.me/?text=${encodeURIComponent(msg)}`;
  window.open(url,'_blank','noopener,noreferrer');
}
function roomDetails(id){
 const r=currentResults.find(x=>x.room.id===id); if(!r)return;
 selectedMapRoom=id;
 $('roomTitle').textContent=r.room.name;
 const blocks=[];
 for(const e of r.list){const prior=blocks.find(x=>x.end===e.start&&x.section===e.section&&x.label===e.label);if(prior)prior.end=e.end;else blocks.push({...e})}
 const cd=countdownLabel(r);
 const canInvite=r.free&&!r.current.length&&r.room.type!=='lab';
 $('roomBody').innerHTML=`<div class="room-hero ${mapStatus(r)}"><div><span class="hero-status">${r.free?'● FREE':r.current.length?'● OCCUPIED':'● '+(r.status==='lab'?'LAB':'UNKNOWN')}</span><h3>${esc(r.room.name)}</h3><p>${floorName(r.room.floor)} · ${r.room.type==='lab'?'Teaching lab':'Classroom'} · ${r.room.capacity!==null?r.room.capacity+' seats':(r.room.capacityRange||'Capacity unknown')} · ${r.room.ac===null?'AC unknown':r.room.ac?'AC':'Non-AC'}</p></div><div class="countdown-box" aria-live="polite"><span>${cd.seconds===0?'NOW':cd.seconds!==null?'LIVE COUNTDOWN':'SCHEDULE'}</span><strong id="roomCountdown">${esc(cd.text)}</strong>${r.next?`<small>Next class: ${time(r.next.start)}${r.next.section?' · '+esc(r.next.section):''}</small>`:'<small>No later class listed today</small>'}</div></div>
 <div class="room-actions">${canInvite?`<button type="button" class="primary squad-btn" id="squadBtn">📢 Call the Squad on WhatsApp</button>`:''}<button type="button" class="quiet" id="mapFocusBtn">View on map</button></div>
 <p>${r.match?'No listed class overlaps your selected stay. Confirm that the room is open and not used by an unlisted section.':r.overlaps.length?'A scheduled class overlaps your selected stay.':r.status==='lab'?'Labs require permission and are not recommended for open study.':'This room does not meet all requested filters, or availability is unknown.'}</p>
 <h3>Classes on this day</h3>${blocks.length?blocks.map(e=>`<div class="schedule-event"><span>${time(e.start)}–${time(e.end)}</span><div>${esc(e.section)} · ${esc(e.label)}<small>${e.ambiguous?'Split-lab entry; both listed venues blocked. ':''}<a href="sources/${encodeURIComponent(e.source)}" target="_blank" rel="noopener">View source PDF ↗</a></small></div></div>`).join(''):'<p>No classes listed for this day. This does not establish actual occupancy or opening hours.</p>'}`;
 $('roomDialog').showModal();
 $('squadBtn')?.addEventListener('click',()=>inviteWhatsApp(r));
 $('mapFocusBtn')?.addEventListener('click',()=>{$('roomDialog').close();document.querySelector(`[data-map-room="${CSS.escape(id)}"]`)?.focus()});
}
function openMetadata(){$('metadataRows').innerHTML=data.rooms.map(r=>{r=metadata(r);return `<tr><td>${esc(r.name)}</td><td><select aria-label="Floor for ${esc(r.name)}" name="floor-${r.id}"><option value="">Unknown</option>${[0,1,2].map(f=>`<option value="${f}" ${r.floor===f?'selected':''}>${floorName(f)}</option>`).join('')}</select></td><td><select name="ac-${r.id}" aria-label="AC for ${esc(r.name)}"><option value="">Unknown</option><option value="yes" ${r.ac===true?'selected':''}>Yes</option><option value="no" ${r.ac===false?'selected':''}>No</option></select></td><td><input aria-label="Capacity for ${esc(r.name)}" name="capacity-${r.id}" type="number" min="1" max="1000" value="${r.capacity??''}" placeholder="Unknown"></td></tr>`}).join('');$('saveFeedback').textContent='';$('metadataDialog').showModal()}
$('metadataForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),rooms={};for(const room of data.rooms){const floor=f.get(`floor-${room.id}`),ac=f.get(`ac-${room.id}`),cap=f.get(`capacity-${room.id}`);rooms[room.id]={floor:floor===''?null:Number(floor),ac:ac===''?null:ac==='yes',capacity:cap===''?null:Number(cap)}}$('saveFeedback').textContent='Saving…';try{const res=await fetch('/api/metadata',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({rooms})});const payload=await res.json();if(!res.ok)throw Error(payload.error||'Could not save room details.');data={...data,rooms:payload.data.rooms};$('saveFeedback').textContent='Saved to the Roomwise server.';render()}catch(err){$('saveFeedback').textContent=err.message}};
function runSearch(text){const parsed=parseSearch(text,read());apply(parsed.query);live=/\b(now|next)\b/i.test(text)&&!(/\b(tomorrow|monday|tuesday|wednesday|thursday|friday|at|from|starting)\b/i.test(text));$('onlyFree').checked=true;render();const q=read();$('searchFeedback').hidden=false;$('searchFeedback').className='feedback';$('searchFeedback').textContent=`Understood: ${q.floor==='all'?'any floor':floorName(Number(q.floor))} · ${q.ac==='any'?'any cooling':q.ac==='yes'?'AC':'non-AC'} · ${q.people?`${q.people} people`:'any group size'} · ${q.date}, ${q.time} for ${q.duration} min. ${parsed.notes.join(' ')} ${currentResults.filter(r=>r.match).length} exact timetable matches.`;return{filters:q,matches:currentResults.filter(r=>r.match).map(r=>({room:r.room.name,freeUntil:time(r.freeUntil)})),notes:parsed.notes}}
async function runServerSearch(text){const res=await fetch('/api/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,base:read()})});const payload=await res.json();if(!res.ok)throw Error(payload.error||'Search failed.');apply(payload.filters);live=/\b(now|next)\b/i.test(text)&&!(/\b(tomorrow|monday|tuesday|wednesday|thursday|friday|at|from|starting)\b/i.test(text));$('onlyFree').checked=true;render();const q=read();$('searchFeedback').hidden=false;$('searchFeedback').className='feedback';$('searchFeedback').textContent=`Understood: ${q.floor==='all'?'any floor':floorName(Number(q.floor))} · ${q.ac==='any'?'any cooling':q.ac==='yes'?'AC':'non-AC'} · ${q.people?`${q.people} people`:'any group size'} · ${q.date}, ${q.time} for ${q.duration} min. ${(payload.notes||[]).join(' ')} ${payload.summary.matches} exact timetable matches.`;return payload}
$('searchForm').onsubmit=async e=>{e.preventDefault();try{await runServerSearch($('query').value)}catch(err){$('searchFeedback').hidden=false;$('searchFeedback').className='feedback error';$('searchFeedback').textContent=err.message}};document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{$('query').value=b.dataset.query;$('searchForm').requestSubmit()});
function setNow(){const n=istNow();$('date').value=n.date;$('time').value=n.time;live=true;render()}$('now').onclick=setNow;
$('filters').onsubmit=e=>e.preventDefault();for(const k of fields)$(k).addEventListener('change',()=>{if(['date','time'].includes(k))live=false;$('searchFeedback').hidden=true;render()});$('onlyFree').onchange=render;$('reset').onclick=()=>{apply({...istNow(),duration:60,floor:'all',ac:'any',people:''});$('query').value='';$('onlyFree').checked=false;$('searchFeedback').hidden=true;live=true;render()};$('detailsBtn').onclick=openMetadata;$('sourcesBtn').onclick=()=>$('sourcesDialog').showModal();$('methodBtn').onclick=()=>$('methodDialog').showModal();document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
function tick(){const n=istNow();$('clock').textContent=`${n.time} IST · ${new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',timeZone:'Asia/Kolkata'}).format(new Date())}`;if(live){$('date').value=n.date;$('time').value=n.time;render()}}
try{const res=await fetch('/api/data');if(!res.ok)throw Error('Could not load the timetable from the Roomwise server.');data=await res.json();apply({...istNow(),duration:60,floor:'all',ac:'any',people:''});$('sourceList').innerHTML=data.sources.map(s=>`<div class="source-row"><a href="sources/${encodeURIComponent(s.name)}" target="_blank" rel="noopener">${esc(s.section)} ↗</a><span>${s.year} · ${s.active?'Active':'Archived'}</span></div>`).join('');tick();setInterval(tick,60000);if(mapTimer)clearInterval(mapTimer);mapTimer=setInterval(()=>{if(data){renderMap();if(selectedMapRoom&&$('roomDialog')?.open){const rr=currentResults.find(x=>x.room.id===selectedMapRoom);if(rr){const cd=countdownLabel(rr);const el=$('roomCountdown');if(el)el.textContent=cd.text;}}}},1000);const context=document.modelContext;if(context?.registerTool){try{await context.registerTool({name:'search_classrooms',title:'Search classrooms',description:'Apply a natural-language classroom search to visible filters. Returns timetable matches, not bookings or confirmed physical occupancy.',inputSchema:{type:'object',properties:{query:{type:'string',minLength:3,maxLength:500}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.query!=='string')throw Error('query must be a string');const result=runSearch(input.query);$('query').value=input.query;return result}})}catch(e){console.warn('Structured classroom search unavailable',e)}}}catch(e){$('results').innerHTML=`<div class="empty"><h3>Timetables could not be loaded</h3><p>${esc(e.message)}</p><button class="textbutton" onclick="location.reload()">Try again</button></div>`;for(const el of document.querySelectorAll('input,select,button'))if(!el.closest('#results'))el.disabled=true}
